    is_shallow: bool,
    add_sha: &str,
    graph_roots: &[String],
) -> bool {
    if !is_shallow {
        return false;
    }
    let add = add_sha.trim();
    if add.len() < MIN_SHA_PREFIX {
        return false;
    }
