33/// Configuration for the agent loop
34pub struct AgentLoopConfig {
35    pub provider: Arc<dyn StreamProvider>,
36    pub model: String,
37    pub api_key: String,
38    pub thinking_level: ThinkingLevel,
39    pub max_tokens: Option<u32>,
40    pub temperature: Option<f32>,
41
42    /// Optional model configuration for multi-provider support.
43    /// When set, passed through to StreamConfig so providers can use
44    /// base_url, headers, compat flags, etc.
45    pub model_config: Option<ModelConfig>,
46
47    /// Convert AgentMessage[] → Message[] before each LLM call.
48    /// Default: keep only LLM-compatible messages.
49    pub convert_to_llm: Option<ConvertToLlmFn>,
50
51    /// Transform context before convert_to_llm (for pruning, compaction).
52    pub transform_context: Option<TransformContextFn>,
53
54    /// Get steering messages (user interruptions mid-run).
55    pub get_steering_messages: Option<GetMessagesFn>,
56
57    /// Get follow-up messages (queued work after agent finishes).
58    pub get_follow_up_messages: Option<GetMessagesFn>,
59
60    /// Context window configuration (auto-compaction).
61    pub context_config: Option<ContextConfig>,
62
63    /// Custom compaction strategy. When set, replaces the default
64    /// `compact_messages()` call. Invoked when `context_config` is `Some`.
65    pub compaction_strategy: Option<Arc<dyn CompactionStrategy>>,
66
67    /// Execution limits (max turns, tokens, duration).
68    pub execution_limits: Option<ExecutionLimits>,
69
70    /// Prompt caching configuration.
71    pub cache_config: CacheConfig,
72
73    /// Tool execution strategy (sequential, parallel, or batched).
74    pub tool_execution: ToolExecutionStrategy,
75
76    /// Tool middleware chain — approve/deny/modify every tool call before it
77    /// executes (see [`ToolMiddleware`]). Empty = allow all.
78    pub tool_middleware: Vec<Arc<dyn ToolMiddleware>>,
79
80    /// Structured-output constraint, passed through to the provider (see
81    /// [`OutputSchema`](crate::provider::OutputSchema)). Usually set via
82    /// [`Agent::prompt_structured`](crate::Agent::prompt_structured).
83    pub output_schema: Option<crate::provider::OutputSchema>,
84
85    /// Retry configuration for transient provider errors.
86    pub retry_config: crate::retry::RetryConfig,
87
88    /// Called before each LLM turn. Return `false` to abort the loop.
89    pub before_turn: Option<BeforeTurnFn>,
90    /// Called after each LLM turn with the current messages and the turn's usage.
91    pub after_turn: Option<AfterTurnFn>,
92    /// Called when the LLM returns a `StopReason::Error`.
93    pub on_error: Option<OnErrorFn>,
94
95    /// Input filters applied to user messages before the LLM call.
96    /// Filters run in order; first `Reject` wins and discards any accumulated
97    /// warnings. `Warn` messages accumulate and are appended to the user message.
98    pub input_filters: Vec<Arc<dyn InputFilter>>,
99
100    /// Optional delay between turns. Useful for rate-limit-sensitive scenarios
101    /// (e.g., OAuth tokens with low request-per-minute caps). Skipped on the
102    /// first turn so the agent starts immediately.
103    pub turn_delay: Option<std::time::Duration>,
104}
