106/// Default convert_to_llm: keep only user/assistant/toolResult messages.
107fn default_convert_to_llm(messages: &[AgentMessage]) -> Vec<Message> {
108    messages
109        .iter()
110        .filter_map(|m| m.as_llm().cloned())
111        .collect()
