230/// Continue an agent loop from existing context (for retries).
231pub async fn agent_loop_continue(
232    context: &mut AgentContext,
233    config: &AgentLoopConfig,
234    tx: mpsc::UnboundedSender<AgentEvent>,
235    cancel: tokio_util::sync::CancellationToken,
236) -> Vec<AgentMessage> {
237    assert!(
238        !context.messages.is_empty(),
239        "Cannot continue: no messages in context"
240    );
241
242    if let Some(last) = context.messages.last() {
243        assert!(
244            last.role() != "assistant",
245            "Cannot continue from assistant message"
246        );
247    }
248
249    let mut new_messages: Vec<AgentMessage> = Vec::new();
250
251    tx.send(AgentEvent::AgentStart).ok();
252    tx.send(AgentEvent::TurnStart).ok();
253
254    let stats = {
255        use tracing::Instrument;
256        run_loop(context, &mut new_messages, config, &tx, &cancel)
257            .instrument(tracing::info_span!("agent_loop", model = %config.model))
258            .await
259    };
260
261    tx.send(AgentEvent::AgentEnd {
262        messages: new_messages.clone(),
263        stats,
264    })
265    .ok();
266    new_messages
267}
