672/// Stream an assistant response from the LLM.
673async fn stream_assistant_response(
674    context: &AgentContext,
675    config: &AgentLoopConfig,
676    tx: &mpsc::UnboundedSender<AgentEvent>,
677    cancel: &tokio_util::sync::CancellationToken,
678) -> Message {
679    // Apply context transform
680    let messages = if let Some(transform) = &config.transform_context {
681        transform(context.messages.clone())
682    } else {
683        context.messages.clone()
684    };
685
686    // Convert to LLM messages
687    let convert = config.convert_to_llm.as_ref();
688    let llm_messages = match convert {
689        Some(f) => f(&messages),
690        None => default_convert_to_llm(&messages),
691    };
692
693    // Build tool definitions
694    let tool_defs: Vec<ToolDefinition> = context
695        .tools
696        .iter()
697        .map(|t| ToolDefinition {
698            name: t.name().to_string(),
699            description: t.description().to_string(),
700            parameters: t.parameters_schema(),
701        })
702        .collect();
703
704    // Retry loop for transient provider errors
705    let retry = &config.retry_config;
706    let mut attempt = 0;
707    let result = loop {
708        let stream_config = StreamConfig {
709            model: config.model.clone(),
710            system_prompt: context.system_prompt.clone(),
711            messages: llm_messages.clone(),
712            tools: tool_defs.clone(),
713            thinking_level: config.thinking_level,
714            api_key: config.api_key.clone(),
715            max_tokens: config.max_tokens,
716            temperature: config.temperature,
717            model_config: config.model_config.clone(),
718            cache_config: config.cache_config.clone(),
719            output_schema: config.output_schema.clone(),
720        };
721
722        let (stream_tx, mut stream_rx) = mpsc::unbounded_channel();
723        let provider_cancel = cancel.clone();
724
725        // Spawn a task to forward events in real-time as the provider streams
726        let event_tx = tx.clone();
727        let model_for_events = config.model.clone();
728        let forward_handle = tokio::spawn(async move {
729            let mut partial_message: Option<AgentMessage> = None;
730            while let Some(event) = stream_rx.recv().await {
731                match &event {
732                    StreamEvent::Start => {
733                        let placeholder = AgentMessage::Llm(Message::Assistant {
734                            content: Vec::new(),
735                            stop_reason: StopReason::Stop,
736                            model: model_for_events.clone(),
737                            provider: String::new(),
738                            usage: Usage::default(),
739                            timestamp: now_ms(),
740                            error_message: None,
741                        });
742                        partial_message = Some(placeholder.clone());
743                        event_tx
744                            .send(AgentEvent::MessageStart {
745                                message: placeholder,
746                            })
747                            .ok();
748                    }
749                    StreamEvent::TextDelta { delta, .. } => {
750                        if let Some(ref msg) = partial_message {
751                            event_tx
752                                .send(AgentEvent::MessageUpdate {
753                                    message: msg.clone(),
754                                    delta: StreamDelta::Text {
755                                        delta: delta.clone(),
756                                    },
757                                })
758                                .ok();
759                        }
760                    }
761                    StreamEvent::ThinkingDelta { delta, .. } => {
762                        if let Some(ref msg) = partial_message {
763                            event_tx
764                                .send(AgentEvent::MessageUpdate {
765                                    message: msg.clone(),
766                                    delta: StreamDelta::Thinking {
767                                        delta: delta.clone(),
768                                    },
769                                })
770                                .ok();
771                        }
772                    }
773                    StreamEvent::ToolCallDelta { delta, .. } => {
774                        if let Some(ref msg) = partial_message {
775                            event_tx
776                                .send(AgentEvent::MessageUpdate {
777                                    message: msg.clone(),
778                                    delta: StreamDelta::ToolCallDelta {
779                                        delta: delta.clone(),
780                                    },
781                                })
782                                .ok();
783                        }
784                    }
785                    StreamEvent::Done { message } => {
786                        let am: AgentMessage = message.clone().into();
787                        partial_message = Some(am.clone());
788                        event_tx.send(AgentEvent::MessageEnd { message: am }).ok();
789                    }
790                    StreamEvent::Error { message } => {
791                        let am: AgentMessage = message.clone().into();
792                        if partial_message.is_none() {
793                            event_tx
794                                .send(AgentEvent::MessageStart {
795                                    message: am.clone(),
796                                })
797                                .ok();
798                        }
799                        partial_message = Some(am.clone());
800                        event_tx.send(AgentEvent::MessageEnd { message: am }).ok();
801                    }
802                    _ => {}
803                }
804            }
805        });
806
807        // Provider streams concurrently — events are forwarded in real-time
808        // When provider returns, stream_tx is dropped, ending the forwarder
809        let result = config
810            .provider
811            .stream(stream_config, stream_tx, provider_cancel)
812            .await;
813
814        match &result {
815            Err(e) if e.is_retryable() && attempt < retry.max_retries && !cancel.is_cancelled() => {
816                // Abort forwarder to prevent forwarding events from failed attempt
817                forward_handle.abort();
818                attempt += 1;
819                // Server-provided Retry-After wins over backoff, but is
820                // clamped to max_delay_ms so a bad header can't stall the loop.
821                let delay = e
822                    .retry_after()
823                    .map(|d| d.min(std::time::Duration::from_millis(retry.max_delay_ms)))
824                    .unwrap_or_else(|| retry.delay_for_attempt(attempt));
825                crate::retry::log_retry(attempt, retry.max_retries, &delay, e);
826                tokio::time::sleep(delay).await;
827                continue;
828            }
829            _ => {
830                // Final attempt — wait for forwarder to finish processing remaining events
831                let _ = forward_handle.await;
832                break result;
833            }
834        }
835    };
836
837    match result {
838        Ok(msg) => msg,
839        Err(e) => {
840            warn!("Provider error: {}", e);
841            Message::Assistant {
842                content: vec![Content::Text {
843                    text: String::new(),
844                }],
845                stop_reason: StopReason::Error,
846                model: config.model.clone(),
847                provider: "unknown".into(),
848                usage: Usage::default(),
849                timestamp: now_ms(),
850                error_message: Some(e.to_string()),
851            }
852        }
853    }
854}
