1//! The core agent loop: prompt → LLM stream → tool execution → repeat.
2//!
3//! This is the heart of yoagent. Inspired by pi-agent-core's agent-loop.ts:
4//!
5//! - `agent_loop()` starts with new prompt messages
6//! - `agent_loop_continue()` resumes from existing context
7//!
8//! Both return a stream of `AgentEvent`s.
9
10use crate::context::{
11    self, CompactionStrategy, ContextConfig, ContextTracker, DefaultCompaction, ExecutionLimits,
12    ExecutionTracker,
13};
14use crate::provider::{ModelConfig, StreamConfig, StreamEvent, StreamProvider, ToolDefinition};
15use crate::types::*;
16use std::sync::Arc;
17
18/// Type alias for convert_to_llm callback.
19pub type ConvertToLlmFn = Box<dyn Fn(&[AgentMessage]) -> Vec<Message> + Send + Sync>;
20/// Type alias for transform_context callback.
21pub type TransformContextFn = Box<dyn Fn(Vec<AgentMessage>) -> Vec<AgentMessage> + Send + Sync>;
22/// Type alias for steering/follow-up message callbacks.
23pub type GetMessagesFn = Box<dyn Fn() -> Vec<AgentMessage> + Send + Sync>;
24/// Called before each LLM turn. Return `false` to abort the loop.
25pub type BeforeTurnFn = Arc<dyn Fn(&[AgentMessage], usize) -> bool + Send + Sync>;
26/// Called after each LLM turn with the current messages and the turn's usage.
27pub type AfterTurnFn = Arc<dyn Fn(&[AgentMessage], &Usage) + Send + Sync>;
28/// Called when the LLM returns a `StopReason::Error`.
29pub type OnErrorFn = Arc<dyn Fn(&str) + Send + Sync>;
30use tokio::sync::mpsc;
31use tracing::warn;
