114/// Start an agent loop with new prompt messages.
115pub async fn agent_loop(
116    prompts: Vec<AgentMessage>,
117    context: &mut AgentContext,
118    config: &AgentLoopConfig,
119    tx: mpsc::UnboundedSender<AgentEvent>,
120    cancel: tokio_util::sync::CancellationToken,
121) -> Vec<AgentMessage> {
122    tx.send(AgentEvent::AgentStart).ok();
123
124    // Apply input filters before adding prompts to context
125    let prompts = if !config.input_filters.is_empty() {
126        let user_text: String = prompts
127            .iter()
128            .filter_map(|m| {
129                if let AgentMessage::Llm(Message::User { content, .. }) = m {
130                    Some(
131                        content
132                            .iter()
133                            .filter_map(|c| {
134                                if let Content::Text { text } = c {
135                                    Some(text.as_str())
136                                } else {
137                                    None
138                                }
139                            })
140                            .collect::<Vec<_>>()
141                            .join("\n"),
142                    )
143                } else {
144                    None
145                }
146            })
147            .collect::<Vec<_>>()
148            .join("\n");
149
150        let mut warnings: Vec<String> = Vec::new();
151        for filter in &config.input_filters {
152            match filter.filter(&user_text) {
153                FilterResult::Pass => {}
154                FilterResult::Warn(w) => warnings.push(w),
155                FilterResult::Reject(reason) => {
156                    tx.send(AgentEvent::InputRejected {
157                        reason: reason.clone(),
158                    })
159                    .ok();
160                    tx.send(AgentEvent::AgentEnd {
161                        messages: vec![],
162                        stats: SessionStats::default(),
163                    })
164                    .ok();
165                    return vec![];
166                }
167            }
168        }
169
170        // Append warnings to the last user message's content (avoids consecutive user messages)
171        if !warnings.is_empty() {
172            let warning_text = warnings
173                .iter()
174                .map(|w| format!("[Warning: {}]", w))
175                .collect::<Vec<_>>()
176                .join("\n");
177
178            let mut modified = prompts;
179            // Find and extend the last user message
180            for msg in modified.iter_mut().rev() {
181                if let AgentMessage::Llm(Message::User { content, .. }) = msg {
182                    content.push(Content::Text { text: warning_text });
183                    break;
184                }
185            }
186            modified
187        } else {
188            prompts
189        }
190    } else {
191        prompts
192    };
193
194    let mut new_messages: Vec<AgentMessage> = prompts.clone();
195
196    // Add prompts to context
197    for prompt in &prompts {
198        context.messages.push(prompt.clone());
199    }
200
201    tx.send(AgentEvent::TurnStart).ok();
202
203    // Emit events for each prompt message
204    for prompt in &prompts {
205        tx.send(AgentEvent::MessageStart {
206            message: prompt.clone(),
207        })
208        .ok();
209        tx.send(AgentEvent::MessageEnd {
210            message: prompt.clone(),
211        })
212        .ok();
213    }
214
215    let stats = {
216        use tracing::Instrument;
217        run_loop(context, &mut new_messages, config, &tx, &cancel)
218            .instrument(tracing::info_span!("agent_loop", model = %config.model))
219            .await
220    };
221
222    tx.send(AgentEvent::AgentEnd {
223        messages: new_messages.clone(),
224        stats,
225    })
226    .ok();
227    new_messages
228}
