269/// Main loop logic shared by agent_loop and agent_loop_continue.
270///
271/// Outer loop: continues when follow-up messages arrive after agent would stop.
272/// Inner loop: process tool calls and steering messages.
273async fn run_loop(
274    context: &mut AgentContext,
275    new_messages: &mut Vec<AgentMessage>,
276    config: &AgentLoopConfig,
277    tx: &mpsc::UnboundedSender<AgentEvent>,
278    cancel: &tokio_util::sync::CancellationToken,
279) -> SessionStats {
280    let mut stats = SessionStats::default();
281    let mut first_turn = true;
282    let mut turn_number: usize = 0;
283    // Rolling growth measurement feeding `compact_headroom_turns`.
284    let mut last_context_tokens: Option<usize> = None;
285    let mut growth_total: usize = 0;
286    let mut growth_samples: usize = 0;
287    // Blends real provider usage with estimation for compaction sizing.
288    let mut context_tracker = ContextTracker::new();
289    let mut tracker = config
290        .execution_limits
291        .as_ref()
292        .map(|limits| ExecutionTracker::new(limits.clone()));
293
294    // Check for steering messages at start
295    let mut pending: Vec<AgentMessage> = config
296        .get_steering_messages
297        .as_ref()
298        .map(|f| f())
299        .unwrap_or_default();
300
301    // Outer loop: follow-ups after agent would stop
302    loop {
303        if cancel.is_cancelled() {
304            return stats;
305        }
306
307        let mut steering_after_tools: Option<Vec<AgentMessage>> = None;
308
309        // Inner loop: runs at least once, then continues if tool calls or pending messages
310        loop {
311            if cancel.is_cancelled() {
312                return stats;
313            }
314
315            if !first_turn {
316                tx.send(AgentEvent::TurnStart).ok();
317            } else {
318                first_turn = false;
319            }
320
321            // Inject pending messages
322            if !pending.is_empty() {
323                for msg in pending.drain(..) {
324                    tx.send(AgentEvent::MessageStart {
325                        message: msg.clone(),
326                    })
327                    .ok();
328                    tx.send(AgentEvent::MessageEnd {
329                        message: msg.clone(),
330                    })
331                    .ok();
332                    context.messages.push(msg.clone());
333                    new_messages.push(msg);
334                }
335            }
336
337            // Check execution limits
338            if let Some(ref tracker) = tracker {
339                if let Some(reason) = tracker.check_limits() {
340                    warn!("Execution limit reached: {}", reason);
341                    let limit_msg = AgentMessage::Llm(Message::User {
342                        content: vec![Content::Text {
343                            text: format!("[Agent stopped: {}]", reason),
344                        }],
345                        timestamp: now_ms(),
346                    });
347                    tx.send(AgentEvent::MessageStart {
348                        message: limit_msg.clone(),
349                    })
350                    .ok();
351                    tx.send(AgentEvent::MessageEnd {
352                        message: limit_msg.clone(),
353                    })
354                    .ok();
355                    context.messages.push(limit_msg.clone());
356                    new_messages.push(limit_msg);
357                    return stats;
358                }
359            }
360
361            // before_turn callback — abort if it returns false
362            if let Some(ref before_turn) = config.before_turn {
363                if !before_turn(&context.messages, turn_number) {
364                    return stats;
365                }
366            }
367
368            // Inter-turn delay — throttle API calls to stay under rate limits.
369            // Skipped on the first turn so the agent starts immediately.
370            if turn_number > 0 {
371                if let Some(delay) = config.turn_delay {
372                    tokio::time::sleep(delay).await;
373                }
374            }
375
376            turn_number += 1;
377
378            // Compact context if configured (tiered: tool outputs → summarize → drop).
379            //
380            // Calibration: the tracker's hybrid figure is anchored on provider
381            // usage, which counts the FULL request (system prompt + tool
382            // schemas + any estimation shortfall on messages), while
383            // `total_tokens` counts messages only. The difference is a
384            // measured overhead; subtracting it from the budget makes the
385            // strategy's message-token checks equivalent to "true window
386            // occupancy <= max_context_tokens". The static
387            // `system_prompt_tokens` reserve is zeroed in the calibrated
388            // config because the measured overhead already includes the real
389            // system prompt. A floor of 10% of the configured budget
390            // guarantees a mis-measured overhead can never wipe the history.
391            if let Some(ref ctx_config) = config.context_config {
392                let estimated = context::total_tokens(&context.messages);
393                let hybrid = context_tracker.estimate_context_tokens(&context.messages);
394                let overhead = hybrid.saturating_sub(estimated);
395
396                // Growth since the last turn's compaction step, averaged. This
397                // is what lets the headroom policy target an interval between
398                // compactions instead of a fixed fraction of the budget: a
399                // ratio cannot know how fast the session is growing, so the
400                // room it leaves shrinks as history accumulates.
401                if let Some(previous) = last_context_tokens {
402                    growth_samples += 1;
403                    growth_total += estimated.saturating_sub(previous);
404                }
405                let growth_per_turn = if growth_samples > 0 {
406                    growth_total as f64 / growth_samples as f64
407                } else {
408                    0.0
409                };
410
411                let calibrated;
412                let effective_config = if overhead > 0 {
413                    let floor = ctx_config.max_context_tokens / 10;
414                    calibrated = ContextConfig {
415                        max_context_tokens: ctx_config
416                            .max_context_tokens
417                            .saturating_sub(overhead)
418                            .max(floor),
419                        system_prompt_tokens: 0,
420                        ..ctx_config.clone()
421                    };
422                    tracing::debug!(
423                        "compaction budget calibrated: {} -> {} (measured overhead: {} tokens)",
424                        ctx_config.max_context_tokens,
425                        calibrated.max_context_tokens,
426                        overhead
427                    );
428                    &calibrated
429                } else {
430                    ctx_config
431                };
432
433                // Resolve the headroom policy against the calibrated budget.
434                let with_headroom;
435                let effective_config = {
436                    let ratio = effective_config.effective_target_ratio(growth_per_turn);
437                    if ratio != effective_config.compact_target_ratio {
438                        tracing::debug!(
439                            "compaction target adapted: ratio {} -> {:.3} \
440                             ({} tokens/turn growth, {:?} turns of headroom)",
441                            effective_config.compact_target_ratio,
442                            ratio,
443                            growth_per_turn as usize,
444                            effective_config.compact_headroom_turns,
445                        );
446                        with_headroom = ContextConfig {
447                            compact_target_ratio: ratio,
448                            ..effective_config.clone()
449                        };
450                        &with_headroom
451                    } else {
452                        effective_config
453                    }
454                };
455
456                let strategy: &dyn CompactionStrategy = config
457                    .compaction_strategy
458                    .as_deref()
459                    .unwrap_or(&DefaultCompaction);
460                let before_len = context.messages.len();
461                // Already computed above over the same unmutated history.
462                let before_tokens = estimated;
463                context.messages =
464                    strategy.compact(std::mem::take(&mut context.messages), effective_config);
465                let after_tokens = context::total_tokens(&context.messages);
466                // Length alone would miss level-1 truncation, which rewrites
467                // tool outputs in place and leaves the count unchanged — and
468                // that is exactly the case where the tracker's baseline goes
469                // stale, so both the reset and the counter key off the same
470                // test rather than the reset keying off length alone.
471                if context.messages.len() != before_len || after_tokens != before_tokens {
472                    // History moved; re-baseline from the next real usage.
473                    context_tracker.reset();
474                    stats.compactions += 1;
475                }
476                last_context_tokens = Some(after_tokens);
477            }
478
479            // Stream assistant response, under an llm_stream span that
480            // records tokens and (when rates are configured) dollar cost.
481            let llm_span = tracing::info_span!(
482                "llm_stream",
483                turn = turn_number,
484                model = %config.model,
485                tokens_in = tracing::field::Empty,
486                tokens_out = tracing::field::Empty,
487                tokens_cached = tracing::field::Empty,
488                cost_usd = tracing::field::Empty,
489                error = tracing::field::Empty,
490            );
491            let message = {
492                use tracing::Instrument;
493                stream_assistant_response(context, config, tx, cancel)
494                    .instrument(llm_span.clone())
495                    .await
496            };
497            if let Message::Assistant {
498                usage, stop_reason, ..
499            } = &message
500            {
501                llm_span.record("error", *stop_reason == StopReason::Error);
502                llm_span.record("tokens_in", usage.input);
503                llm_span.record("tokens_out", usage.output);
504                llm_span.record("tokens_cached", usage.cache_read);
505                if let Some(mc) = &config.model_config {
506                    if mc.cost.is_configured() {
507                        llm_span.record("cost_usd", mc.cost.cost_usd(usage));
508                    }
509                }
510            }
511            // Tool-forcing providers (Anthropic) deliver structured output as
512            // a forced tool call — unwrap it into plain text BEFORE tool-call
513            // extraction, so the loop never tries to execute the synthetic tool.
514            let message = unwrap_structured_tool_call(message, config.output_schema.as_ref());
515
516            let agent_msg: AgentMessage = message.clone().into();
517            context.messages.push(agent_msg.clone());
518            new_messages.push(agent_msg.clone());
519            if let Message::Assistant { usage, .. } = &message {
520                context_tracker.record_usage(usage, context.messages.len() - 1);
521                stats.record_turn(usage, config.model_config.as_ref().map(|mc| &mc.cost));
522            }
523
524            // Check for error/abort
525            if let Message::Assistant {
526                ref stop_reason,
527                ref error_message,
528                ref usage,
529                ..
530            } = message
531            {
532                if *stop_reason == StopReason::Error || *stop_reason == StopReason::Aborted {
533                    if *stop_reason == StopReason::Error {
534                        if let Some(ref on_error) = config.on_error {
535                            let err_str = error_message.as_deref().unwrap_or("Unknown error");
536                            on_error(err_str);
537                        }
538                    }
539                    // Call after_turn even on error/abort so callers tracking usage don't miss this turn
540                    if let Some(ref after_turn) = config.after_turn {
541                        after_turn(&context.messages, usage);
542                    }
543                    tx.send(AgentEvent::TurnEnd {
544                        message: agent_msg,
545                        tool_results: vec![],
546                    })
547                    .ok();
548                    return stats;
549                }
550            }
551
552            // Extract tool calls
553            let tool_calls: Vec<_> = match &message {
554                Message::Assistant { content, .. } => content
555                    .iter()
556                    .filter_map(|c| match c {
557                        Content::ToolCall {
558                            id,
559                            name,
560                            arguments,
561                            ..
562                        } => Some((id.clone(), name.clone(), arguments.clone())),
563                        _ => None,
564                    })
565                    .collect(),
566                _ => vec![],
567            };
568
569            let has_tool_calls = !tool_calls.is_empty();
570            let mut tool_results: Vec<Message> = Vec::new();
571
572            if has_tool_calls {
573                let execution = execute_tool_calls(
574                    &context.tools,
575                    &tool_calls,
576                    tx,
577                    cancel,
578                    config.get_steering_messages.as_ref(),
579                    &config.tool_execution,
580                    &config.tool_middleware,
581                )
582                .await;
583
584                tool_results = execution.tool_results;
585                steering_after_tools = execution.steering_messages;
586
587                // Cap oversized output on the way in when configured, so
588                // compaction never has to rewrite a tool result the provider
589                // has already cached. Per-tool budgets apply, so a tool that
590                // tolerates head+tail badly can opt out. The events emitted
591                // above still carry the untruncated output — this is a context
592                // concern only.
593                let append_cap = config
594                    .context_config
595                    .as_ref()
596                    .filter(|c| c.truncate_tool_output_on_append);
597
598                for result in &tool_results {
599                    let mut am: AgentMessage = result.clone().into();
600                    if let Some(ctx_config) = append_cap {
601                        am = context::truncate_tool_output(am, ctx_config);
602                    }
603                    context.messages.push(am.clone());
604                    new_messages.push(am);
605                }
606            }
607
608            // Track turn for execution limits
609            if let Some(ref mut tracker) = tracker {
610                let turn_tokens = match &message {
611                    Message::Assistant { usage, .. } => {
612                        (usage.input + usage.output + usage.cache_read + usage.cache_write) as usize
613                    }
614                    _ => context::message_tokens(&agent_msg),
615                };
616                tracker.record_turn(turn_tokens);
617            }
618
619            // after_turn callback
620            if let Some(ref after_turn) = config.after_turn {
621                let usage = match &message {
622                    Message::Assistant { usage, .. } => usage.clone(),
623                    _ => Usage::default(),
624                };
625                after_turn(&context.messages, &usage);
626            }
627
628            tx.send(AgentEvent::TurnEnd {
629                message: agent_msg,
630                tool_results,
631            })
632            .ok();
633
634            // Check steering after turn
635            if let Some(steering) = steering_after_tools.take() {
636                if !steering.is_empty() {
637                    pending = steering;
638                    continue;
639                }
640            }
641
642            pending = config
643                .get_steering_messages
644                .as_ref()
645                .map(|f| f())
646                .unwrap_or_default();
647
648            // Exit inner loop if no more tool calls and no pending messages
649            if !has_tool_calls && pending.is_empty() {
650                break;
651            }
652        }
653
654        // Agent would stop. Check for follow-ups.
655        let follow_ups = config
656            .get_follow_up_messages
657            .as_ref()
658            .map(|f| f())
659            .unwrap_or_default();
660
661        if !follow_ups.is_empty() {
662            pending = follow_ups;
663            continue;
664        }
665
666        break;
667    }
668
669    stats
670}
