857// Tool execution
858// ---------------------------------------------------------------------------
859
860struct ToolExecutionResult {
861    tool_results: Vec<Message>,
862    steering_messages: Option<Vec<AgentMessage>>,
863}
864
865/// Convert a forced structured-output tool call back into a plain-text
866/// assistant message with `StopReason::Stop`. No-op unless a schema is set
867/// and the message carries a tool call named after it.
868fn unwrap_structured_tool_call(
869    message: Message,
870    schema: Option<&crate::provider::OutputSchema>,
871) -> Message {
872    let Some(schema) = schema else {
873        return message;
874    };
875    let Message::Assistant {
876        content,
877        model,
878        provider,
879        usage,
880        stop_reason,
881        error_message,
882        ..
883    } = &message
884    else {
885        return message;
886    };
887    let Some(payload) = content.iter().find_map(|c| match c {
888        Content::ToolCall {
889            name, arguments, ..
890        } if *name == schema.name => Some(arguments.clone()),
891        _ => None,
892    }) else {
893        return message;
894    };
895
896    // Remove ONLY the synthetic call; any real tool calls (shouldn't occur
897    // under forced tool_choice, but defensively) stay and execute normally.
898    // The payload is appended AFTER any preamble text — consumers take the
899    // last text block.
900    let mut new_content: Vec<Content> = content
901        .iter()
902        .filter(|c| !matches!(c, Content::ToolCall { name, .. } if *name == schema.name))
903        .cloned()
904        .collect();
905    new_content.push(Content::Text {
906        text: payload.to_string(),
907    });
908    // ToolUse becomes Stop (the forced call was the "answer"); every other
909    // stop reason (Length = truncated payload, Error, ...) is preserved so
910    // truncation isn't laundered into success.
911    let new_stop = if *stop_reason == StopReason::ToolUse {
912        StopReason::Stop
913    } else {
914        stop_reason.clone()
915    };
916    let rebuilt = Message::assistant(
917        new_content,
918        new_stop,
919        model.clone(),
920        provider.clone(),
921        usage.clone(),
922    );
923    // `Message::assistant` nulls `error_message`, so carry it across explicitly.
924    // The stop reason is preserved a few lines up for the same reason; dropping
925    // the explanation with it leaves the caller a bare `Error` and
926    // `StructuredPromptError::Provider { message: "provider error (no detail)" }`.
927    match error_message {
928        Some(msg) => rebuilt.with_error_message(msg.clone()),
929        None => rebuilt,
930    }
931}
932
933async fn execute_tool_calls(
934    tools: &[Box<dyn AgentTool>],
935    tool_calls: &[(String, String, serde_json::Value)],
936    tx: &mpsc::UnboundedSender<AgentEvent>,
937    cancel: &tokio_util::sync::CancellationToken,
938    get_steering: Option<&GetMessagesFn>,
939    strategy: &ToolExecutionStrategy,
940    middleware: &[Arc<dyn ToolMiddleware>],
941) -> ToolExecutionResult {
942    match strategy {
943        ToolExecutionStrategy::Sequential => {
944            execute_sequential(tools, tool_calls, tx, cancel, get_steering, middleware).await
945        }
946        ToolExecutionStrategy::Parallel => {
947            execute_batch(tools, tool_calls, tx, cancel, get_steering, middleware).await
948        }
949        ToolExecutionStrategy::Batched { size } => {
950            let mut results: Vec<Message> = Vec::new();
951            let mut steering_messages: Option<Vec<AgentMessage>> = None;
952
953            for (batch_idx, batch) in tool_calls.chunks(*size).enumerate() {
954                let batch_result = execute_batch(tools, batch, tx, cancel, None, middleware).await;
955                results.extend(batch_result.tool_results);
956
957                // Check steering between batches
958                if let Some(get_steering_fn) = get_steering {
959                    let steering = get_steering_fn();
960                    if !steering.is_empty() {
961                        steering_messages = Some(steering);
962                        // Skip remaining batches
963                        let executed = (batch_idx + 1) * *size;
964                        if executed < tool_calls.len() {
965                            for (skip_id, skip_name, _) in &tool_calls[executed..] {
966                                results.push(skip_tool_call(skip_id, skip_name, tx));
967                            }
968                        }
969                        break;
970                    }
971                }
972            }
973
974            ToolExecutionResult {
975                tool_results: results,
976                steering_messages,
977            }
978        }
979    }
980}
981
982/// Execute tool calls one at a time, checking steering between each.
983async fn execute_sequential(
984    tools: &[Box<dyn AgentTool>],
985    tool_calls: &[(String, String, serde_json::Value)],
986    tx: &mpsc::UnboundedSender<AgentEvent>,
987    cancel: &tokio_util::sync::CancellationToken,
988    get_steering: Option<&GetMessagesFn>,
989    middleware: &[Arc<dyn ToolMiddleware>],
990) -> ToolExecutionResult {
991    let mut results: Vec<Message> = Vec::new();
992    let mut steering_messages: Option<Vec<AgentMessage>> = None;
993
994    for (index, (id, name, args)) in tool_calls.iter().enumerate() {
995        let (result_msg, _is_error) =
996            execute_single_tool(tools, id, name, args, tx, cancel, middleware).await;
997        results.push(result_msg);
998
999        // Check for steering — skip remaining tools if user interrupted
1000        if let Some(get_steering_fn) = get_steering {
1001            let steering = get_steering_fn();
1002            if !steering.is_empty() {
1003                steering_messages = Some(steering);
1004                for (skip_id, skip_name, _) in &tool_calls[index + 1..] {
1005                    results.push(skip_tool_call(skip_id, skip_name, tx));
1006                }
1007                break;
1008            }
1009        }
1010    }
1011
1012    ToolExecutionResult {
1013        tool_results: results,
1014        steering_messages,
1015    }
1016}
1017
1018/// Execute a batch of tool calls concurrently using futures::join_all.
1019async fn execute_batch(
1020    tools: &[Box<dyn AgentTool>],
1021    tool_calls: &[(String, String, serde_json::Value)],
1022    tx: &mpsc::UnboundedSender<AgentEvent>,
1023    cancel: &tokio_util::sync::CancellationToken,
1024    get_steering: Option<&GetMessagesFn>,
1025    middleware: &[Arc<dyn ToolMiddleware>],
1026) -> ToolExecutionResult {
1027    use futures::future::join_all;
1028
1029    let futures: Vec<_> = tool_calls
1030        .iter()
1031        .map(|(id, name, args)| execute_single_tool(tools, id, name, args, tx, cancel, middleware))
1032        .collect();
1033
1034    let batch_results = join_all(futures).await;
1035
1036    let results: Vec<Message> = batch_results.into_iter().map(|(msg, _)| msg).collect();
1037
1038    // Check steering after batch completes
1039    let steering_messages = if let Some(get_steering_fn) = get_steering {
1040        let steering = get_steering_fn();
1041        if steering.is_empty() {
1042            None
1043        } else {
1044            Some(steering)
1045        }
1046    } else {
1047        None
1048    };
1049
1050    ToolExecutionResult {
1051        tool_results: results,
1052        steering_messages,
1053    }
1054}
1055
1056/// Execute a single tool call and emit events.
1057async fn execute_single_tool(
1058    tools: &[Box<dyn AgentTool>],
1059    id: &str,
1060    name: &str,
1061    args: &serde_json::Value,
1062    tx: &mpsc::UnboundedSender<AgentEvent>,
1063    cancel: &tokio_util::sync::CancellationToken,
1064    middleware: &[Arc<dyn ToolMiddleware>],
1065) -> (Message, bool) {
1066    // Middleware chain runs first: each hook may rewrite the args seen by
1067    // later hooks; the first Deny short-circuits into an error tool result
1068    // (the LLM sees the reason and can adapt — the loop continues).
1069    let mut effective_args = args.clone();
1070    for mw in middleware {
1071        let call = ToolCallRequest {
1072            tool_call_id: id,
1073            tool_name: name,
1074            args: &effective_args,
1075        };
1076        // A panicking middleware must not kill the loop task (which would
1077        // strip the agent of its tools) — contain it and fail closed.
1078        let decision = {
1079            use futures::FutureExt;
1080            std::panic::AssertUnwindSafe(mw.before_tool(&call))
1081                .catch_unwind()
1082                .await
1083                .unwrap_or_else(|_| {
1084                    tracing::warn!(tool = name, "tool middleware panicked; denying the call");
1085                    ToolDecision::Deny("tool middleware panicked".into())
1086                })
1087        };
1088        match decision {
1089            ToolDecision::Allow => {}
1090            ToolDecision::Modify(new_args) => effective_args = new_args,
1091            ToolDecision::Deny(reason) => {
1092                return denied_tool_call(id, name, &effective_args, &reason, tx);
1093            }
1094        }
1095    }
1096    let args = &effective_args;
1097
1098    let tool = tools.iter().find(|t| t.name() == name);
1099
1100    // The Start event carries the effective (post-middleware) args — what
1101    // actually runs.
1102    tx.send(AgentEvent::ToolExecutionStart {
1103        tool_call_id: id.to_string(),
1104        tool_name: name.to_string(),
1105        args: args.clone(),
1106    })
1107    .ok();
1108
1109    let on_update: Option<ToolUpdateFn> = {
1110        let tx = tx.clone();
1111        let id = id.to_string();
1112        let name = name.to_string();
1113        Some(Arc::new(move |partial: ToolResult| {
1114            tx.send(AgentEvent::ToolExecutionUpdate {
1115                tool_call_id: id.clone(),
1116                tool_name: name.clone(),
1117                partial_result: partial,
1118            })
1119            .ok();
1120        }))
1121    };
1122
1123    let on_progress: Option<ProgressFn> = {
1124        let tx = tx.clone();
1125        let id = id.to_string();
1126        let name = name.to_string();
1127        Some(Arc::new(move |text: String| {
1128            tx.send(AgentEvent::ProgressMessage {
1129                tool_call_id: id.clone(),
1130                tool_name: name.clone(),
1131                text,
1132            })
1133            .ok();
1134        }))
1135    };
1136
1137    let ctx = ToolContext {
1138        tool_call_id: id.to_string(),
1139        tool_name: name.to_string(),
1140        cancel: cancel.child_token(),
1141        on_update,
1142        on_progress,
1143    };
1144
1145    let tool_span = tracing::info_span!(
1146        "tool",
1147        tool = %name,
1148        tool_call_id = %id,
1149        is_error = tracing::field::Empty,
1150    );
1151    use tracing::Instrument;
1152    let (result, is_error) = match tool {
1153        Some(tool) => {
1154            let execution = tool
1155                .execute(args.clone(), ctx)
