1212/// Emit events and build the error tool result for a middleware-denied call.
1213/// Start/End are both emitted so UI event pairing stays intact.
1214fn denied_tool_call(
1215    id: &str,
1216    name: &str,
1217    args: &serde_json::Value,
1218    reason: &str,
1219    tx: &mpsc::UnboundedSender<AgentEvent>,
1220) -> (Message, bool) {
1221    // Operator-visible signal: without this, a denial exists only in the
1222    // event stream / message history, invisible to telemetry.
1223    tracing::warn!(
1224        tool = name,
1225        tool_call_id = id,
1226        reason,
1227        "tool call denied by middleware"
1228    );
1229    tx.send(AgentEvent::ToolExecutionStart {
1230        tool_call_id: id.to_string(),
1231        tool_name: name.to_string(),
1232        args: args.clone(),
1233    })
1234    .ok();
1235
1236    let result = ToolResult {
1237        content: vec![Content::Text {
1238            text: format!("Tool call denied: {}", reason),
1239        }],
1240        details: serde_json::Value::Null,
1241    };
1242
1243    tx.send(AgentEvent::ToolExecutionEnd {
1244        tool_call_id: id.to_string(),
1245        tool_name: name.to_string(),
1246        result: result.clone(),
1247        is_error: true,
1248    })
1249    .ok();
1250
