{"text":"// Hook system — pre/post tool execution pipeline
// ---------------------------------------------------------------------------

use std::collections::HashMap;
use std::sync::Arc;

use yoagent::types::{AgentTool, ToolError, ToolResult};
use yoagent::Content;

/// Bytes of the *head* of a hook's stderr kept by [`cap_hook_stderr`].
///
/// Deliberately the same budget `CAPTURE_HEAD_BYTES` in `src/commands_run.rs` uses for
/// `/run`, and for the same reason: a hook's stderr reaches the model's context verbatim
/// (`PostHookResult::with_feedback`), so an unbounded one can overflow the conversation
/// and wedge the session (#844). Head **and** tail rather than tail-only, because a hook's
/// *first* error line is the actionable one while its last lines are usually the summary —
/// a tail-only cut throws away the line the user actually needs.
const HOOK_STDERR_HEAD_BYTES: usize = 4096;
/// Bytes of the *tail* of a hook's stderr kept by [`cap_hook_stderr`]. See
/// [`HOOK_STDERR_HEAD_BYTES`].
const HOOK_STDERR_TAIL_BYTES: usize = 4096;

/// Bound a hook's stderr to `head` + `tail` bytes before it enters the conversation.
///
/// At or under budget the input is returned **byte-identically** — that is every hook
/// anyone has today and is the whole regression surface. Over budget the middle is
/// dropped and the cut is marked **in band**, because a silent elision is the bug (the
/// same rule `/run`, `/bg`, `!` and `/ast` already follow).
///
/// Both cuts land on a `char` boundary and are never taken by raw byte index (rule #250 —
/// `s[..n]` panics inside a multi-byte character): the head walks *back* and the tail walks
/// *forward*, so a character straddling either cut is dropped **whole** rather than split.
fn cap_hook_stderr(raw: &str, head: usize, tail: usize) -> String {
    if raw.len() <= head + tail {
        return raw.to_string();
    }

    let mut head_end = head;
    while head_end > 0 && !raw.is_char_boundary(head_end) {
        head_end -= 1;
    }

    let mut tail_start = raw.len() - tail;
    while tail_start < raw.len() && !raw.is_char_boundary(tail_start) {
        tail_start += 1;
    }
    // A pathological `head`/`tail` pair must not produce overlapping slices.
    if tail_start < head_end {
        tail_start = head_end;
    }

    let dropped = tail_start - head_end;
    format!(
        "{}\n… [yoyo: {dropped} bytes elided — hook stderr is capped at {head} head + {tail} tail bytes]\n{}",
        &raw[..head_end],
        &raw[tail_start..],
    )
}

/// Result returned by a post-hook, carrying both the (possibly modified) output
/// and optional feedback that will be injected into the agent's context.
///
/// Feedback is additional context from the hook — e.g. linter warnings, security
/// scan results — that the agent should see on its next turn. It's separate from
/// the tool output itself so hooks can add information without modifying what the
/// tool actually returned.
#[derive(Debug, Clone, PartialEq)]
pub struct PostHookResult {
    /// The (possibly modified) tool output, threaded through the hook chain.
    pub output: String,
    /// Optional feedback to inject into the agent's context. `None` means the hook
    /// has nothing extra to say; the tool result passes through unchanged.
    pub feedback: Option<String>,
}

impl PostHookResult {
    /// Convenience: wrap output with no feedback.
    pub fn passthrough(output: &str) -> Self {
        Self {
            output: output.to_string(),","citations":["https://github.com/yologdev/yoyo-evolve/blob/7bcb8caa94e8ae0816cee7b8235012f551edc94c/src/hooks.rs#L1"]}

{"text":"/// The parameter list mirrors [`classify_turn_end`]'s inputs exactly (plus the
/// verdict); the call site feeds both from the same variables so the two can't
/// drift apart.
pub(crate) fn format_turn_end_debug(
    end: TurnEnd,
    queue_pending: usize,
    used_tools: bool,
    had_error: bool,
    continues_used: u32,
    max_continues: u32,
    final_text_chars: usize,
) -> String {
    let yn = |b: bool| if b { "yes" } else { "no" };
    let verdict = match end {
        TurnEnd::Done => "done",
        TurnEnd::Paused => "paused",
        TurnEnd::BudgetSpent => "budget_spent",
    };
    format!(
        "turn state: queue={queue_pending} tools={} error={} \
         continues={continues_used}/{max_continues} final_text={final_text_chars}ch -> {verdict}",
        yn(used_tools),
        yn(had_error),
    )
}

/// Format a dim one-line hint naming the next queued follow-up item.
///
/// `count` is the number of items pending in the follow-up queue; `first` is
/// the text of the next queued item. Returns `None` (print nothing) when the
/// queue is empty (`count == 0`) or the first item is blank — this keeps the
/// hint a product-safe no-op for providers that don't populate the queue.
///
/// The first item is truncated char-boundary-safely (via `truncate_with_ellipsis`)
/// so a multi-byte first character never panics.
pub(crate) fn format_followup_hint(count: usize, first: &str) -> Option<String> {
    let first = first.trim();
    if count == 0 || first.is_empty() {
        return None;
    }
    let preview = truncate_with_ellipsis(first, 60);
    Some(format!("↻ continuing — {count} pending: {preview}"))
}

/// Extract a short preview of the next queued follow-up item from a yoagent
/// follow-up-queue snapshot. Returns the trimmed text of the first LLM message's
/// first text content block, or an empty string if the snapshot has no usable
/// text (e.g. providers that don't populate the queue).
fn first_followup_text(snapshot: &[yoagent::AgentMessage]) -> String {
    for msg in snapshot {
        if let Some(yoagent::Message::User { content, .. }) = msg.as_llm() {
            for block in content {
                if let yoagent::Content::Text { text } = block {
                    let t = text.trim();
                    if !t.is_empty() {
                        return t.to_string();
                    }
                }
            }
        }
    }
    String::new()
}

/// Heuristic check: does the agent's response text suggest it stopped mid-work
/// and intends to continue? Conservative — only triggers on clear signals.
pub(crate) fn looks_incomplete(text: &str) -> bool {
    let text = text.trim();
    if text.is_empty() || text.len() < 20 {
        return false;
    }

    // Check the tail of the response (last ~300 chars) for continuation signals.
    let tail_start = safe_byte_index(text, text.len().saturating_sub(300));
    let tail = &text[tail_start..];
    let tail_lower = tail.to_lowercase();

    // ── Completion guard ──
    // When the tail contains strong completion signals, weaker patterns (action
    // phrases, ellipsis with work signals, ordinal progression) are likely being","citations":["https://github.com/yologdev/yoyo-evolve/blob/7bcb8caa94e8ae0816cee7b8235012f551edc94c/src/repl.rs#L1691"]}

