        CategoryPrefix::UnknownCategory(cat) => {
            eprintln!("{RED}  {}{RESET}\n", unknown_category_message(cat));
            return;
        }","citations":["https://github.com/yologdev/yoyo-evolve/blob/7bcb8caa94e8ae0816cee7b8235012f551edc94c/src/commands_memory.rs#L1"]}

